fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function to lowercase an ASCII uppercase letter
    // 'A'..='Z' -> 'a'..='z', else unchanged.
    fn ascii_lowercase(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Convert uppercase ASCII to lowercase by adding 32
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    for i in 0..len / 2 {
        let left = ascii_lowercase(text[i]);
        let right = ascii_lowercase(text[len - 1 - i]);
        if left != right {
            return false;
        }
    }
    true
}